+message VerifyPaymentRequest {
+  string tx_hash = 1;
+  int64 expected_amount = 2;
+  string expected_recipient = 3;
+}
+
+message VerifyPaymentResponse {
+  bool verified = 1;
+  string payment_id = 2;
+  int64 amount = 3;
+  string status = 4;
+  int64 block_height = 5;
+  google.protobuf.Timestamp confirmed_at = 6;
+}
+
+message SubmitTransactionRequest {
+  string from = 1;
+  string to = 2;
+  int64 value = 3;
+  bytes data = 4;
+  bytes signature = 5;
+  string public_key = 6;
+  bytes pqc_signature = 7;
+}
+
+message SubmitTransactionResponse {
+  string tx_hash = 1;
+  string status = 2;
+}
+
+message GetBalanceRequest {
+  string address = 1;
+}
+
+message GetBalanceResponse {
+  int64 balance = 1;
+}
+
+message GetBlockHeightRequest {}
+
+message GetBlockHeightResponse {
+  uint64 height = 1;
+}
+
+message RegisterDVENodeRequest {
+  string node_id = 1;
+  string owner_address = 2;
+  int64 stake_amount = 3;
+}
+
+message RegisterDVENodeResponse {
+  string tx_hash = 1;
+  bool success = 2;
+}
+
+message CreateChainSessionRequest {
+  string dve_node_id = 1;
+  string owner_address = 2;
+}
+
+message CreateChainSessionResponse {
+  string session_id = 1;
+  google.protobuf.Timestamp expires_at = 2;
+  bytes pqc_signature = 3;
+}
+
+message ValidateSessionRequest {
+  string session_id = 1;
+}
+
+message ValidateSessionResponse {
+  bool valid = 1;
+  google.protobuf.Timestamp expires_at = 2;
+}
+
+message GetSecretRequest {
+  string session_id = 1;
+  string secret_key = 2;
+}
+
+message GetSecretResponse {
+  string secret_value = 1;
+  bool success = 2;
+}

Index: shared-proto/chain/v1/chain.proto
===================================================================
--- shared-proto/chain/v1/chain.proto	
+++ shared-proto/chain/v1/chain.proto	
@@ -0,0 +1,87 @@
+syntax = "proto3";
+
+package knirv.chain.v1;
+
+option go_package = "github.com/guiperry/KNIRV_NETWORK/pkg/gen/knirv/chain/v1;chainv1";
+
+// LoRaAdapterSkill represents a LoRA adapter skill stored on KNIRVCHAIN.
+// Weights are stored as packed bytes for efficient serialization.
+message LoRaAdapterSkill {
+  // Metadata
+  string skill_id = 1;
+  string skill_name = 2;
+  string description = 3;
+  string base_model_compatibility = 4;
+  uint32 version = 5;
+
+  // LoRA parameters
+  int32 rank = 6;
+  float alpha = 7;
+
+  // LoRA weight matrices (packed float arrays)
+  bytes weights_a = 8;
+  bytes weights_b = 9;
+
+  map<string, string> additional_metadata = 10;
+}
+
+// Response from a skill invocation on KNIRVCHAIN
+message SkillInvocationResponse {
+  string invocation_id = 1;
+  Status status = 2;
+  string error_message = 3;
+  LoRaAdapterSkill skill = 4;
+}
+
+// Request to invoke a skill by ID
+message SkillInvocationRequest {
+  string invocation_id = 1;
+  string skill_id = 2;
+  map<string, string> parameters = 3;
+  string agent_core_id = 4;
+}
+
+// Request to compile a new skill from solutions and errors
+message SkillCompilationRequest {
+  string compilation_id = 1;
+  SkillMetadata metadata = 2;
+  SkillTrainingData training_data = 3;
+}
+
+message SkillMetadata {
+  string skill_name = 1;
+  string description = 2;
+  string base_model = 3;
+  int32 rank = 4;
+  float alpha = 5;
+  map<string, string> additional_metadata = 6;
+}
+
+message SkillTrainingData {
+  repeated Solution solutions = 1;
+  repeated ErrorNode errors = 2;
+}
+
+message Solution {
+  string error_id = 1;
+  string solution = 2;
+  float confidence = 3;
+  string agent_id = 4;
+  int64 timestamp = 5;
+}
+
+message ErrorNode {
+  string error_id = 1;
+  string description = 2;
+  string context = 3;
+  string cluster_id = 4;
+  int64 timestamp = 5;
+}
+
+enum Status {
+  STATUS_UNSPECIFIED = 0;
+  SUCCESS = 1;
+  FAILURE = 2;
+  NOT_FOUND = 3;
+  COMPILATION_IN_PROGRESS = 4;
+}

Index: shared-proto/graph/v1/graph.proto
===================================================================
--- shared-proto/graph/v1/graph.proto	
+++ shared-proto/graph/v1/graph.proto	
@@ -0,0 +1,114 @@
+syntax = "proto3";
+
+package knirv.graph.v1;
+
+import "google/protobuf/timestamp.proto";
+import "google/protobuf/struct.proto";
+
+option go_package = "github.com/guiperry/KNIRV_NETWORK/pkg/gen/knirv/graph/v1;graphv1";
+
+// ErrorContext is the rich data payload sent by a KNIRV agent to KNIRVGRAPH
+// when it encounters an error. The graph uses this to find similar ErrorNodes.
+message ErrorContext {
+  // Agent information
+  string agent_id = 1;
+  string agent_version = 2;
+  string base_model_id = 3;
+
+  // Environment information
+  string os = 4;
+  string architecture = 5;
+  string runtime_environment = 6; // "browser", "native_host", "knirv-nexus-dve"
+
+  // Error details
+  string error_type = 7;
+  string error_message = 8;
+  string stack_trace = 9;
+  string source_code_snippet = 10;
+
+  // Task context
+  string task_description = 11;
+  string input_data_hash = 12;
+  string skill_invoked_id = 13;
+
+  // State and metadata
+  string agent_state_hash = 14;
+  google.protobuf.Timestamp timestamp = 15;
+  google.protobuf.Struct additional_context = 16;
+}
+
+// Request to query KNIRVGRAPH for similar error clusters
+message ErrorClusterQueryRequest {
+  ErrorContext error_context = 1;
+  int32 max_results = 2;
+  float similarity_threshold = 3;
+}
+
+// Response from KNIRVGRAPH error cluster query
+message ErrorClusterQueryResponse {
+  QueryStatus status = 1;
+  string error_message = 2;
+  SkillNodeResult skill_node_result = 3;
+  repeated ErrorCluster similar_clusters = 4;
+}
+
+// Skill node result from KNIRVGRAPH
+message SkillNodeResult {
+  string skill_uri = 1;
+  string skill_node_id = 2;
+  string cluster_id = 3;
+  float confidence = 4;
+  map<string, string> metadata = 5;
+}
+
+// Error cluster information
+message ErrorCluster {
+  string cluster_id = 1;
+  string error_type = 2;
+  int32 error_count = 3;
+  float average_severity = 4;
+  repeated string tags = 5;
+  int64 bounty_amount = 6;
+}
+
+// Request to submit a new error node to KNIRVGRAPH
+message ErrorNodeSubmissionRequest {
+  ErrorContext error_context = 1;
+  int64 bounty_amount = 2;
+  ErrorPriority priority = 3;
+}
+
+// Response from error node submission
+message ErrorNodeSubmissionResponse {
+  SubmissionStatus status = 1;
+  string error_message = 2;
+  string error_node_id = 3;
+  string cluster_id = 4;
+}
+
+// Query status enumeration
+enum QueryStatus {
+  QUERY_STATUS_UNSPECIFIED = 0;
+  QUERY_SUCCESS = 1;
+  QUERY_FAILED = 2;
+  QUERY_NO_MATCH = 3;
+  QUERY_PARTIAL_MATCH = 4;
+}
+
+// Submission status enumeration
+enum SubmissionStatus {
+  SUBMISSION_STATUS_UNSPECIFIED = 0;
+  SUBMISSION_SUCCESS = 1;
+  SUBMISSION_FAILED = 2;
+  SUBMISSION_DUPLICATE = 3;
+  SUBMISSION_INVALID = 4;
+}
+
+// Error priority enumeration
+enum ErrorPriority {
+  ERROR_PRIORITY_UNSPECIFIED = 0;
+  LOW = 1;
+  MEDIUM = 2;
+  HIGH = 3;
+  CRITICAL = 4;
+}

Index: shared-proto/hasher/v1/hasher.proto
===================================================================
--- shared-proto/hasher/v1/hasher.proto	
+++ shared-proto/hasher/v1/hasher.proto	
@@ -0,0 +1,223 @@
+syntax = "proto3";
+
+package hasher.v1;
+
+option go_package = "knirvhasher/proto/hasher/v1;hasherv1";
+
+// HasherService provides ASIC computation services (KNIRVHASHER hardware interface).
+service HasherService {
+  rpc ComputeHash(ComputeHashRequest) returns (ComputeHashResponse);
+  rpc ComputeBatch(ComputeBatchRequest) returns (ComputeBatchResponse);
+  rpc StreamCompute(stream StreamComputeRequest) returns (stream StreamComputeResponse);
+  rpc GetMetrics(GetMetricsRequest) returns (GetMetricsResponse);
+  rpc GetDeviceInfo(GetDeviceInfoRequest) returns (GetDeviceInfoResponse);
+  rpc MineWork(MineWorkRequest) returns (MineWorkResponse);
+  rpc VerifyMath(VerifyMathRequest) returns (VerifyMathResponse);
+}
+
+// HasherTrainingService provides dataset collection and training pipeline services.
+// Used by KNIRVSERVER to push DVE data to KNIRVHASHER for model training.
+service HasherTrainingService {
+  rpc ExportSecurityData(ExportRequest) returns (stream EncryptedChunk);
+  rpc TriggerTraining(TrainingRequest) returns (TrainingResponse);
+  rpc GetTrainingStatus(TrainingStatusRequest) returns (TrainingStatusResponse);
+  rpc GetUserRules(RulesRequest) returns (RulesResponse);
+  rpc ValidateAction(ActionRequest) returns (ActionResponse);
+  rpc StreamActivity(StreamActivityRequest) returns (stream ActivityEvent);
+}
+
+message ComputeHashRequest {
+  bytes data = 1;
+}
+
+message ComputeHashResponse {
+  bytes hash = 1;
+  uint64 latency_us = 2;
+}
+
+message ComputeBatchRequest {
+  repeated bytes data = 1;
+  uint32 max_batch_size = 2;
+}
+
+message ComputeBatchResponse {
+  repeated bytes hashes = 1;
+  uint64 total_latency_us = 2;
+  uint32 processed_count = 3;
+}
+
+message StreamComputeRequest {
+  bytes data = 1;
+  uint64 request_id = 2;
+}
+
+message StreamComputeResponse {
+  bytes hash = 1;
+  uint64 request_id = 2;
+  uint64 latency_us = 3;
+}
+
+message GetMetricsRequest {}
+
+message GetMetricsResponse {
+  uint64 total_requests = 1;
+  uint64 total_bytes_processed = 2;
+  uint64 average_latency_us = 3;
+  uint64 peak_latency_us = 4;
+  uint64 total_errors = 5;
+  uint64 cache_hits = 6;
+  uint64 cache_misses = 7;
+  map<string, uint64> device_stats = 8;
+}
+
+message GetDeviceInfoRequest {}
+
+message GetDeviceInfoResponse {
+  string device_path = 1;
+  uint32 chip_count = 2;
+  string firmware_version = 3;
+  bool is_operational = 4;
+  uint64 uptime_seconds = 5;
+}
+
+message MineWorkRequest {
+  bytes header = 1;
+  uint32 nonce_start = 2;
+  uint32 nonce_end = 3;
+}
+
+message MineWorkResponse {
+  uint32 nonce = 1;
+  uint64 latency_us = 2;
+}
+
+message VerifyMathRequest {
+  string context = 1;
+  string proposition = 2;
+  uint32 subdomain = 3;
+  float confidence_threshold = 4;
+}
+
+message VerifyMathResponse {
+  string status = 1;
+  string nonce = 2;
+  string result_hash = 3;
+  string detokenized_output = 4;
+  float logic_integrity = 5;
+  float latency_ms = 6;
+}
+
+message ExportRequest {
+  string org_id = 1;
+  string user_id = 2;
+  DataType data_type = 3;
+  bool encrypted = 4;
+  int64 since_timestamp = 5;
+}
+
+enum DataType {
+  ALL = 0;
+  ONTOLOGY = 1;
+  GUARDRAILS = 2;
+  ACTIVITY = 3;
+  MARKDOWN = 4;
+  USERS = 5;
+}
+
+message EncryptedChunk {
+  bytes data = 1;
+  string chunk_id = 2;
+  bool is_last = 3;
+  int32 chunk_index = 4;
+  int32 total_chunks = 5;
+}
+
+message TrainingRequest {
+  string org_id = 1;
+  string user_id = 2;
+  TrainingTrigger trigger = 3;
+  map<string, string> options = 4;
+  string training_id = 5;
+}
+
+enum TrainingTrigger {
+  ON_DEMAND = 0;
+  SCHEDULED = 1;
+  GUARDRAIL_VIOLATION = 2;
+}
+
+message TrainingResponse {
+  string training_id = 1;
+  string status = 2;
+}
+
+message TrainingStatusRequest {
+  string training_id = 1;
+}
+
+message TrainingStatusResponse {
+  string training_id = 1;
+  string status = 2;
+  uint32 progress = 3;
+  string error = 4;
+  int32 epochs_completed = 5;
+  int32 total_epochs = 6;
+  float best_fitness = 7;
+}
+
+message RulesRequest {
+  string user_id = 1;
+  string org_id = 2;
+  RuleType rule_type = 3;
+}
+
+enum RuleType {
+  RULE_ALL = 0;
+  RULE_GUARDRAIL = 1;
+  RULE_ONTOLOGY = 2;
+  RULE_ACTION = 3;
+}
+
+message SecurityRule {
+  string id = 1;
+  string name = 2;
+  string pattern = 3;
+  RuleType rule_type = 4;
+  string action = 5;
+}
+
+message RulesResponse {
+  repeated SecurityRule rules = 1;
+}
+
+message ActionRequest {
+  string user_id = 1;
+  string action = 2;
+  map<string, string> context = 3;
+}
+
+message ActionResponse {
+  bool allowed = 1;
+  float confidence = 2;
+  repeated string violations = 3;
+  repeated string applied_rules = 4;
+  string seed_id = 5;
+  string decision_id = 6;
+}
+
+message StreamActivityRequest {
+  string user_id = 1;
+  string org_id = 2;
+  int64 since_timestamp = 3;
+  repeated string event_types = 4;
+}
+
+message ActivityEvent {
+  string event_id = 1;
+  string event_type = 2;
+  string user_id = 3;
+  string org_id = 4;
+  string payload = 5;
+  int64 timestamp = 6;
+  map<string, string> data = 7;
+}

